      const backendValidationErrors = parseActionValidationErrors(error);
      const actionErrorCode = parseActionErrorCode(error);
      const statusCode = error?.response?.status;
      let fallbackManualErrors = [];

      if (actionErrorCode === SELF_VERIFICATION_NOT_ALLOWED_CODE) {
        setActionValidationErrors([]);
        Notification(
          t("common:errorTitle", { defaultValue: "Greska" }),
          t("common:selfVerificationNotAllowed", {
            defaultValue: "Ne mozete verifikovati transakciju koju ste vi menjali.",
          }),
          "error",
          "topRight"
        );
        return false;
      }

      if (actionErrorCode === TX_LOCKED_CODE) {
        setActionValidationErrors([]);
        setIsLockBlocked(true);
        notifyLockedByOtherUser(parseLockOwner(error));
        return false;
      }

      if (statusCode === 409 && actionErrorCode !== TX_LOCKED_CODE && isPresent(transactionId)) {
        try {
          const manualErrorsResponse = await transactionApi?.getManualValidationErrors?.(transactionId);
          fallbackManualErrors = mapManualValidationErrors(manualErrorsResponse?.data);
        } catch {
          fallbackManualErrors = [];
        }
      }

      const validationErrorsToShow =
        statusCode === 409 && fallbackManualErrors.length > 0
          ? fallbackManualErrors
          : backendValidationErrors.length > 0
          ? backendValidationErrors
          : fallbackManualErrors;

      if (validationErrorsToShow.length > 0) {
        setActionValidationErrors(validationErrorsToShow);
        Notification(
          "Greska",
          "Validacija nije uspesna. Ispravite greske i pokusajte ponovo.",
          "error",
          "topRight"
        );
      } else {
        setActionValidationErrors([]);
        const backendMessage = parseActionErrorMessage(error);
        Notification(
          "Greska",
          backendMessage || "Neuspesno izvrsavanje akcije.",
          "error",
          "topRight"
        );
      }
      return false;
    } finally {
      setActiveAction(null);
    }
  };

  const handleReturnForCorrection = () =>
    (async () => {
      if (!actionPermissions.returnForCorrection) {
        notifyActionNotAllowed();
        return;
      }

      await runTransactionAction(
        "returnForCorrection",
        transactionApi.returnForCorrection,
        "Nalog je vracen na doradu."
      );
    })();

  const handleForceProcessing = () =>
    (async () => {
      if (transactionStatusCode === MANUAL_ENTRY_STATUS_SOURCE) {
        if (!actionPermissions.sendToManualEntry) {
          notifyActionNotAllowed();
          return;
        }

        await runTransactionAction(
          "forceProcessing",
          transactionApi.forceProcessing,
          "Nalog je poslat na rucni unos.",
          "S7"
        );
        return;
      }

      if (EDITABLE_STATUS_CODES.has(transactionStatusCode)) {
        if (!actionPermissions.forceVerification) {
          notifyActionNotAllowed();
          return;
        }

        if (canEditDetails && hasDetailsChanges) {
          const valuesToSave = detailsDraft || mapRawOrderToEditableForm(rawOrder);
          const saved = await handleSaveDetails(valuesToSave);
          if (!saved) {
            return;
          }
        }

        await runTransactionAction(
          "sendForVerificationForce",
          transactionApi.sendForVerificationForce,
          "Nalog je poslat na verifikaciju forsiranja.",
          "S7C"
        );
      }
    })();

  const handleSendForVerification = () =>
    (async () => {
      if (!actionPermissions.sendForVerification) {
        notifyActionNotAllowed();
        return;
      }

      if (canEditDetails && hasDetailsChanges) {
        const valuesToSave = detailsDraft || mapRawOrderToEditableForm(rawOrder);
        const saved = await handleSaveDetails(valuesToSave);
        if (!saved) {
          return;
        }
      }

      await runTransactionAction(
        "sendForVerification",
        transactionApi.sendForVerification,
        "Nalog je poslat na verifikaciju.",
        "S7A"
      );
    })();

  const handleApproveVerification = () =>
    (async () => {
      if (!actionPermissions.approveVerification) {
        notifyActionNotAllowed();
        return;
      }

      if (canEditDetails && hasDetailsChanges) {
        const valuesToSave = detailsDraft || mapRawOrderToEditableForm(rawOrder);
        const saved = await handleSaveDetails(valuesToSave);
        if (!saved) {
          return;
        }
      }

      await runTransactionAction(
        "approveVerification",
        transactionApi.approveVerification,
        "Nalog je odobren.",
        "S10"
      );
    })();

  const handleRestoreFromError = () =>
    (async () => {
      if (!actionPermissions.restoreFromError) {
        notifyActionNotAllowed();
        return;
      }

      if (transactionStatusCode !== ERROR_STATUS_CODE) {
        Notification(
          "Greska",
          "Akcija je dostupna samo za naloge u statusu S11.",
          "error",
          "topRight"
        );
        return;
      }

      if (!isPresent(transactionId)) {
        Notification(
          "Greska",
          "Nije moguce pokrenuti vracanje iz greske bez transaction ID.",
          "error",
          "topRight"
        );
        return;
      }

      await runTransactionAction(
        "restoreFromError",
        () => restoreFromError(transactionId),
        "Nalog je vracen iz greske."
      );
    })();

  const closeRejectModal = () => {
    if (activeAction === "sendForVerificationReject") {
      return;
    }

    setIsRejectModalOpen(false);
    setSelectedRejectCode(null);
  };

  const loadRejectOptions = async () => {
    setIsLoadingRejects(true);
    try {
      const response = await getRejects();
      const mappedOptions = mapRejectOptions(response?.data);
      setRejectOptions(mappedOptions);

      if (mappedOptions.length === 0) {
        Notification(
          t("common:errorTitle", { defaultValue: "Greska" }),
          t("common:rejectReasonEmpty", {
            defaultValue: "Lista razloga odbijanja je prazna.",
          }),
          "error",
          "topRight"
        );
        return false;
      }

      return true;
    } catch (error) {
      Notification(
        t("common:errorTitle", { defaultValue: "Greska" }),
        t("common:rejectReasonLoadFailed", {
          defaultValue: "Neuspesno ucitavanje razloga odbijanja.",
        }),
        "error",
        "topRight"
      );
      return false;
    } finally {
      setIsLoadingRejects(false);
    }
  };

  const handleRejectModalConfirm = async () => {
    if (!isPresent(selectedRejectCode)) {
      Notification(
        t("common:errorTitle", { defaultValue: "Greska" }),
        t("common:rejectReasonRequired", {
          defaultValue: "Izaberite razlog odbijanja.",
        }),
        "error",
        "topRight"
      );
      return;
    }

    const selectedOption = rejectOptions.find(
      (option) => option?.value === selectedRejectCode
    );

    const isSuccess = await runTransactionAction(
      "sendForVerificationReject",
      (id) =>
        transactionApi.sendForVerificationReject(id, {
          rejectCode: selectedRejectCode,
          rejectReason: selectedOption?.reason || null,
        }),
      "Nalog je poslat na verifikaciju odbijanja.",
      "S7B"
    );

    if (isSuccess) {
      setIsRejectModalOpen(false);
      setSelectedRejectCode(null);
    }
  };

  const handleSendForVerificationReject = () =>
    (async () => {
      if (!actionPermissions.rejectTransaction) {
        notifyActionNotAllowed();
        return;
      }

      if (canEditDetails && hasDetailsChanges) {
        const valuesToSave = detailsDraft || mapRawOrderToEditableForm(rawOrder);
        const saved = await handleSaveDetails(valuesToSave);
        if (!saved) {
          return;
        }
      }

      const loaded = await loadRejectOptions();
      if (!loaded) {
        return;
      }

      setSelectedRejectCode(null);
      setIsRejectModalOpen(true);
    })();

  const handleSaveDetails = async (formValues) => {
    if (!canEditDetails || !transactionId) {
      Notification(
        "Greska",
        "Snimanje detalja je dostupno samo za naloge u statusu S7 ili S12.",
        "error",
        "topRight"
      );
      return false;
    }

    if (validateLocalManualEntryLengths(formValues, t).length > 0) {
      notifyLocalValidationFailed();
      return false;
    }

    if (lockRequired && (isLockLoading || isLockBlocked)) {
      Notification(
        t("common:errorTitle", { defaultValue: "Greska" }),
        t("common:transactionLockedActive", {
          defaultValue: "Transakcija je zakljucana za izmenu.",
        }),
        "error",
        "topRight"
      );
      return false;
    }

    setIsSavingDetails(true);
    const payload = mapEditableFormToPayload(formValues);

    try {
      const response = await transactionApi.updateManualEntryDetails(transactionId, payload);
      const responseData =
        response?.data && typeof response.data === "object" ? response.data : {};

      const mergedRawOrder = {
        ...rawOrder,
        ...payload,
        ...responseData,
      };

      setEditableOrder(mergedRawOrder);
      setDetailsDraft(mapRawOrderToEditableForm(mergedRawOrder));
      setHasDetailsChanges(false);
      notifyOrderUpdated(mergedRawOrder);
      Notification("Uspeh", "Detalji su uspesno sacuvani.", "success", "topRight");
      return true;
    } catch (error) {
      const actionErrorCode = parseActionErrorCode(error);
      if (actionErrorCode === TX_LOCKED_CODE) {
        setIsLockBlocked(true);
        notifyLockedByOtherUser(parseLockOwner(error));
        return false;
      }
      Notification("Greska", "Neuspesno snimanje detalja.", "error", "topRight");
      return false;
    } finally {
      setIsSavingDetails(false);
    }
  };

  const handleDetailsDraftChange = (values, hasChanges) => {
    setDetailsDraft(values);
    setHasDetailsChanges(Boolean(hasChanges));
  };

  const handleDrawerClose = async () => {
    if (isSavingDetails) {
      return;
    }

    if (canEditDetails && hasDetailsChanges) {
      const shouldSave = await askSaveChangesConfirmation(t);
      if (shouldSave) {
        const valuesToSave = detailsDraft || mapRawOrderToEditableForm(rawOrder);
        const saved = await handleSaveDetails(valuesToSave);
        if (!saved) {
          return;
        }
      } else {
        resetToPersistedDetailsState(
          selectedOrder,
          setEditableOrder,
          setDetailsDraft,
          setHasDetailsChanges
        );
      }
