      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const isoLikeDateMatch = asText.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2})(?::(\d{2}))?)?/
  );
  if (isoLikeDateMatch) {
