            return record?.[rowKey];
          }
          return record?.id;
        })
        .map(toTransactionId)
        .filter((value) => value !== null),
    [rowKey, tableDataForExport]
  );

  const handleExportClick = async () => {
    const payload = {
      transactionIds: exportTransactionIds,
      columns: exportColumns,
    };

    if (!payload.transactionIds.length) {
      message.warning(
        t("common:exportNoRows", {
          defaultValue: "Nema transakcija za izvoz.",
        })
      );
      return;
    }

    if (!payload.columns.length) {
      message.warning(
        t("common:exportNoColumns", {
          defaultValue: "Nema kolona za izvoz.",
        })
      );
      return;
    }

    if (typeof onExport === "function") {
      await onExport(payload);
      return;
    }

    setIsExporting(true);
    try {
      const response = await exportTransactionsExcel(payload);
      const contentDisposition = response?.headers?.["content-disposition"];
      const fileName =
        parseFileNameFromContentDisposition(contentDisposition) ||
        "transactions.xlsx";
      const contentType =
        response?.headers?.["content-type"] ||
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
      const fileBlob = new Blob([response?.data], { type: contentType });
      triggerFileDownload(fileBlob, fileName);
    } catch (error) {
      message.error(
        t("common:exportFailed", {
          defaultValue: "Neuspesan izvoz u Excel.",
        })
      );
    } finally {
      setIsExporting(false);
    }
  };

  const handleTableChange = (nextPagination, _, __, extra) => {
    setPaginationState((prev) => {
      const nextCurrent = nextPagination?.current ?? prev.current;
      const nextPageSize = nextPagination?.pageSize ?? prev.pageSize;
      if (nextCurrent === prev.current && nextPageSize === prev.pageSize) {
        return prev;
      }
      return {
        current: nextCurrent,
        pageSize: nextPageSize,
      };
    });

    if (Array.isArray(extra?.currentDataSource)) {
      setTableDataForExport(extra.currentDataSource);
      return;
    }
    setTableDataForExport(dataSource);
  };

  const handleArchiveSearchFieldChange = (field, value) => {
    setArchiveSearchFilters((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleArchiveSearchSubmit = async () => {
    if (!canSearchArchive || loading) return;

    const receivedDateFrom = toPickerDate(archiveSearchFilters.receivedDateFrom);
    const receivedDateTo = toPickerDate(archiveSearchFilters.receivedDateTo);

    if (receivedDateFrom && receivedDateTo) {
      if (receivedDateFrom.getTime() > receivedDateTo.getTime()) {
        message.error(
          t("common:archiveSearchInvalidRange", {
            defaultValue: 'Polje "Datum prijema (od)" mora biti manje ili jednako polju "Datum prijema (do)".',
          })
        );
        return;
      }

      if (receivedDateTo.getTime() > addMonths(receivedDateFrom, 6).getTime()) {
        message.error(
          t("common:archiveSearchRangeLimit", {
            defaultValue:
              'Period izmedju polja "Datum prijema (od)" i "Datum prijema (do)" ne sme biti duzi od 6 meseci.',
          })
        );
        return;
      }
    }

    try {
      const searchResult = await onArchiveSearch(
        buildArchiveSearchPayload(archiveSearchFilters)
      );
      if (searchResult !== false) {
        setIsArchiveSearchModalOpen(false);
      }
    } catch (error) {
      // Parent handles user-facing error state.
    }
  };

  return (
    <section className={`${styles.wrapper} ${className}`.trim()}>
      {showToolbar ? (
        <div className={styles.toolbar}>
          <SearchData
            value={searchQuery}
            onChange={setSearchQuery}
            placeholder={t("common:search", { defaultValue: "Pretraga" })}
            tooltip={searchTooltip}
          />
          <div className={styles.toolbarActions}>
            <Button
              type="default"
              className={styles.toolbarButton}
              icon={<AppstoreOutlined />}
              onClick={openColumnsModal}
              disabled={!configurableColumns.length}
            >
              {t("common:changeColumns", {
                defaultValue: "Change columns",
              })}
            </Button>
            <Button
              type="default"
              className={styles.toolbarButton}
              icon={<DownloadOutlined />}
              onClick={handleExportClick}
              loading={isExporting}
              disabled={
                isExporting ||
                exportColumns.length === 0 ||
                exportTransactionIds.length === 0
              }
            >
              {t("common:exportExcel", { defaultValue: "Export Excel" })}
            </Button>
            {canSearchArchive ? (
              <Button
                type="default"
                className={styles.toolbarButton}
                icon={<SearchOutlined />}
                onClick={openArchiveSearchModal}
                disabled={loading}
              >
                {t("common:archiveSearch", { defaultValue: "Pretraga arhive" })}
              </Button>
            ) : null}
          </div>
        </div>
      ) : null}

      <Table
        className={styles.table}
        columns={visibleColumns}
        dataSource={dataSource}
        loading={loading}
        rowKey={rowKey}
        onChange={handleTableChange}
        onRow={
          typeof onView === "function"
            ? (record) => ({
                onDoubleClick: () => onView(record),
              })
            : undefined
        }
        scroll={{ x: "max-content" }}
        showSorterTooltip={false}
        pagination={{
          current: paginationState.current,
          pageSize: paginationState.pageSize,
          size: "small",
          showSizeChanger: true,
          pageSizeOptions: ["10", "20", "50"],
        }}
      />

      <Modal
        title={t("common:changeColumns", { defaultValue: "Change columns" })}
        open={isColumnsModalOpen}
        onCancel={closeColumnsModal}
        onOk={saveColumnsSelection}
        okText={t("common:save", { defaultValue: "Sacuvaj" })}
        cancelText={t("common:cancel", { defaultValue: "Odustani" })}
        okButtonProps={{ disabled: draftSelectedColumnKeys.length === 0 }}
      >
        <div className={styles.columnsModalList}>
          {draftColumnOrderKeys.map((columnId, index) => {
            const column = columnsById.get(columnId);
            if (!column || !configurableColumnSet.has(columnId)) return null;

            return (
              <div key={columnId} className={styles.columnOptionRow}>
                <label className={styles.columnOption}>
                  <Checkbox
                    checked={draftSelectedColumnKeys.includes(columnId)}
                    onChange={(event) => {
                      const checked = event.target.checked;
                      setDraftSelectedColumnKeys((prev) => {
                        if (checked) return Array.from(new Set([...prev, columnId]));
                        return prev.filter((key) => key !== columnId);
                      });
                    }}
                  >
                    {getColumnLabel(column)}
                  </Checkbox>
                </label>
                <div className={styles.columnOrderActions}>
                  <Button
                    type="text"
                    size="small"
                    icon={<ArrowUpOutlined />}
                    disabled={index === 0}
                    onClick={() =>
                      setDraftColumnOrderKeys((prev) => moveItem(prev, index, -1))
                    }
                  />
                  <Button
                    type="text"
                    size="small"
                    icon={<ArrowDownOutlined />}
                    disabled={index === draftColumnOrderKeys.length - 1}
                    onClick={() =>
                      setDraftColumnOrderKeys((prev) => moveItem(prev, index, 1))
                    }
                  />
                </div>
              </div>
            );
          })}
        </div>
      </Modal>

      <Modal
        title={t("common:archiveSearch", { defaultValue: "Pretraga arhive" })}
        open={isArchiveSearchModalOpen}
        onCancel={closeArchiveSearchModal}
        onOk={handleArchiveSearchSubmit}
        okText={t("common:search", { defaultValue: "Pretraga" })}
        cancelText={t("common:cancel", { defaultValue: "Odustani" })}
        okButtonProps={{ loading, disabled: loading }}
        cancelButtonProps={{ disabled: loading }}
        destroyOnClose={false}
      >
        <div className={styles.archiveSearchForm}>
          <div className={styles.archiveSearchField}>
            <label className={styles.archiveSearchLabel} htmlFor="archive-core-id">
              {t("columns:coreId", { defaultValue: "Core ID" })}
            </label>
            <Input
              id="archive-core-id"
              value={archiveSearchFilters.coreId}
              onChange={(event) =>
                handleArchiveSearchFieldChange("coreId", event.target.value)
              }
              placeholder={t("columns:coreId", { defaultValue: "Core ID" })}
              disabled={loading}
              allowClear
            />
          </div>

          <div className={styles.archiveSearchField}>
            <label className={styles.archiveSearchLabel} htmlFor="archive-reference">
              {t("columns:reference", { defaultValue: "Reference" })}
            </label>
            <Input
              id="archive-reference"
              value={archiveSearchFilters.reference}
              onChange={(event) =>
                handleArchiveSearchFieldChange("reference", event.target.value)
              }
              placeholder={t("columns:reference", { defaultValue: "Reference" })}
              disabled={loading}
              allowClear
            />
          </div>

          <div className={styles.archiveSearchDateGrid}>
            <div className={styles.archiveSearchField}>
              <label className={styles.archiveSearchLabel}>
                {t("common:archiveSearchDateFrom", {
                  defaultValue: "Datum prijema (od)",
                })}
              </label>
              <DatePicker
                value={archiveSearchFilters.receivedDateFrom}
                onChange={(value) =>
                  handleArchiveSearchFieldChange("receivedDateFrom", value)
                }
                format="DD/MM/YYYY"
                disabled={loading}
                allowClear
              />
            </div>

            <div className={styles.archiveSearchField}>
              <label className={styles.archiveSearchLabel}>
                {t("common:archiveSearchDateTo", {
                  defaultValue: "Datum prijema (do)",
                })}
              </label>
              <DatePicker
                value={archiveSearchFilters.receivedDateTo}
                onChange={(value) =>
                  handleArchiveSearchFieldChange("receivedDateTo", value)
                }
                format="DD/MM/YYYY"
                disabled={loading}
                allowClear
              />
            </div>
          </div>
        </div>
      </Modal>
    </section>
  );
};

export default withTranslation(["common", "columns"])(DataTable);

