import React, { useCallback, useEffect, useMemo, useState } from "react";
import { withTranslation } from "react-i18next";
import { useLocation } from "react-router-dom";
import Header from "../../parts/header/Header";
import DataTable from "../../components/DataTable/DataTable";
import Drawer from "../../components/Drawer/Drawer";
import columns, {
  TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY,
} from "../Incoming/columns";
import Notification from "../../components/Notification/Notification";
import {
  ALL_ORDERS,
  ALL_ORDERS_ERRORS,
  ALL_ORDERS_INCOMING,
  ALL_ORDERS_OUTGOING,
} from "../../components/routes";
import {
  getAll as getIncomingAll,
  getErrors as getIncomingErrors,
} from "../../services/incomingService/service";
import {
  getAll as getOutgoingAll,
  getErrors as getOutgoingErrors,
} from "../../services/outgoingService/service";
import {
  extractTransactionItems,
  mapTransactionListItems,
} from "../../utils/transactionListMapper";

const firstRejectedReason = (results = []) => {
  const rejected = results.find((entry) => entry?.status === "rejected");
  return rejected?.reason || new Error("Neuspesno ucitavanje podataka.");
};

const mergeRequests = async (requests = []) => {
  const results = await Promise.allSettled(requests.map((request) => request()));
  const successful = results
    .filter((entry) => entry.status === "fulfilled")
    .flatMap((entry) => extractTransactionItems(entry.value));

  if (successful.length === 0) {
    throw firstRejectedReason(results);
  }

  return successful;
};

const getCombinedAll = () =>
  mergeRequests([() => getIncomingAll(), () => getOutgoingAll()]);

const getCombinedErrors = () =>
  mergeRequests([() => getIncomingErrors(), () => getOutgoingErrors()]);

const ALL_ORDERS_ROUTE_SETTINGS = [
  {
    path: ALL_ORDERS_OUTGOING,
    titleKey: "sidebar:outgoingOrders",
    titleDefault: "PlaÄ‡anja",
    loadData: getOutgoingAll,
    fallbackLoadData: getCombinedAll,
  },
  {
    path: ALL_ORDERS_INCOMING,
    titleKey: "sidebar:incomingOrders",
    titleDefault: "Prilivi",
    loadData: getIncomingAll,
    fallbackLoadData: getCombinedAll,
  },
  {
    path: ALL_ORDERS_ERRORS,
    titleKey: "sidebar:errors",
    titleDefault: "GreÅ¡ke",
    loadData: getCombinedErrors,
    fallbackLoadData: getCombinedAll,
  },
  {
    path: ALL_ORDERS,
    titleKey: "sidebar:allOrders",
    titleDefault: "Sve poruke",
    loadData: getCombinedAll,
  },
];

const normalizePath = (path) => {
  if (!path) return "";
  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
  return path;
};

const resolveRouteSettings = (pathname) => {
  const normalizedPath = normalizePath(pathname);
  const matchedRoute = ALL_ORDERS_ROUTE_SETTINGS.find(
    (route) => normalizePath(route.path) === normalizedPath
  );
  return (
    matchedRoute ||
    ALL_ORDERS_ROUTE_SETTINGS.find((route) => route.path === ALL_ORDERS) ||
    ALL_ORDERS_ROUTE_SETTINGS[0]
  );
};

const toTransactionItems = (responseOrItems) => {
  if (Array.isArray(responseOrItems)) return responseOrItems;
  return extractTransactionItems(responseOrItems);
};

const AllOrdersBase = ({ t }) => {
  const location = useLocation();
  const { titleKey, titleDefault, loadData, fallbackLoadData } = useMemo(
    () => resolveRouteSettings(location.pathname),
    [location.pathname]
  );
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState(null);

  const refreshCurrentRouteItems = useCallback(async () => {
    try {
      const response = await loadData();
      const mappedItems = mapTransactionListItems(
        toTransactionItems(response)
      );
      setItems(mappedItems);
      return;
    } catch (primaryError) {
      if (!fallbackLoadData) {
        return;
      }
    }

    try {
      const response = await fallbackLoadData();
      const mappedItems = mapTransactionListItems(
        toTransactionItems(response)
      );
      setItems(mappedItems);
    } catch (fallbackError) {
      // Keep current optimistic row state if refresh fails.
    }
  }, [fallbackLoadData, loadData]);

  const handleView = (record) => {
    if (record?.canOpenDrawer === false) {
      return;
    }
    setSelectedOrder(record || null);
    setIsDrawerOpen(true);
  };

  const handleCloseDrawer = () => {
    setIsDrawerOpen(false);
  };

  const handleOrderUpdated = (updatedOrder) => {
    if (!updatedOrder || updatedOrder.id === null || updatedOrder.id === undefined) {
      return;
    }

    setSelectedOrder(updatedOrder);
    setItems((currentItems) =>
      currentItems.map((item) => {
        if (String(item?.id) !== String(updatedOrder.id)) {
          return item;
        }
        return {
          ...item,
          ...updatedOrder,
          statusCode: updatedOrder.statusCode || item?.statusCode,
          status: updatedOrder.status || item?.status,
          _raw: {
            ...(item?._raw || {}),
            ...(updatedOrder?._raw || {}),
          },
        };
      })
    );

    void refreshCurrentRouteItems();
  };

  useEffect(() => {
    if (top !== self) {
      top.location = self.location;
    }

    let cancelled = false;

    const fetchAllOrders = async () => {
      setLoading(true);
      try {
        const response = await loadData();
        const mappedItems = mapTransactionListItems(
          toTransactionItems(response)
        );
        if (!cancelled) {
          setItems(mappedItems);
        }
      } catch (primaryError) {
        if (!fallbackLoadData) {
          if (!cancelled) {
            Notification(
              t("notification:incoming:error", { defaultValue: "Greska" }),
              t("notification:incoming:message", {
                defaultValue: "Neuspesno ucitavanje podataka.",
              }),
              "error",
              "topRight"
            );
          }
          return;
        }

        try {
          const response = await fallbackLoadData();
          const mappedItems = mapTransactionListItems(
            toTransactionItems(response)
          );
          if (!cancelled) {
            setItems(mappedItems);
          }
        } catch (fallbackError) {
          if (!cancelled) {
            Notification(
              t("notification:incoming:error", { defaultValue: "Greska" }),
              t("notification:incoming:message", {
                defaultValue: "Neuspesno ucitavanje podataka.",
              }),
              "error",
              "topRight"
            );
          }
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    fetchAllOrders();

    return () => {
      cancelled = true;
    };
  }, [fallbackLoadData, loadData, t]);

  return (
    <>
      <Header title={t(titleKey, { defaultValue: titleDefault })} />
      <DataTable
        items={items}
        columns={columns}
        loading={loading}
        onView={handleView}
        columnVisibilityStorageKey={TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY}
      />
      <Drawer
        open={isDrawerOpen}
        onClose={handleCloseDrawer}
        selectedOrder={selectedOrder}
        onOrderUpdated={handleOrderUpdated}
      />
    </>
  );
};

export default withTranslation(["privatePage"])(AllOrdersBase);

