import React from "react";
import { Input } from "antd";
import { SearchOutlined } from "@ant-design/icons";
import { withTranslation } from "react-i18next";
import styles from "./SearchData.module.css";

const SearchData = ({
  t,
  value = "",
  onChange,
  placeholder,
  className = "",
  allowClear = true,
  tooltip,
}) => {
  const { Search } = Input;
  const tooltipText = typeof tooltip === "string" ? tooltip : undefined;

  const searchInput = (
    <Search
      value={value}
      onChange={(event) => onChange?.(event.target.value)}
      onSearch={(nextValue) => onChange?.(nextValue)}
      placeholder={
        placeholder || t("common:search", { defaultValue: "Pretraga" })
      }
      allowClear={allowClear}
      enterButton={<SearchOutlined className={styles.icon} />}
      className={`${styles.input} ${className}`.trim()}
    />
  );

  if (!tooltipText) {
    return searchInput;
  }

  return (
    <span className={styles.tooltipWrapper} title={tooltipText}>
      {searchInput}
    </span>
  );
};

export default withTranslation(["common"])(SearchData);

