import rs.unicredit.cbr.repository.ActionLogRepository;
import rs.unicredit.cbr.service.ActionLogService;
import rs.unicredit.cbr.service.CurrentUserService;

@Service
@RequiredArgsConstructor
public class ActionLogServiceImpl implements ActionLogService {

    private final ActionLogRepository actionLogRepository;
    private final ActionLogMapper actionLogMapper;
    private final CurrentUserService currentUserService;

    @Override
    @Transactional
    public ActionLogDto create(ActionLogDto actionLogDto) {
        CbrActionLog saved = actionLogRepository.save(actionLogMapper.toEntity(actionLogDto));
        return actionLogMapper.toDto(saved);
    }

    @Override
    @Transactional
    public ActionLogDto logAction(String requestId, String action, Map<String, Object> changes) {
        if (requestId == null || requestId.isBlank()) {
            throw new IllegalArgumentException("requestId is required for action log entry.");
        }
        if (action == null || action.isBlank()) {
            throw new IllegalArgumentException("action is required for action log entry.");
        }

        String username = resolveCurrentUsername();
        ActionLogDto dto = ActionLogDto.builder()
                .requestId(requestId.trim())
                .username(username)
                .action(action.trim())
                .changes(changes == null ? new LinkedHashMap<>() : new LinkedHashMap<>(changes))
                .createdBy(username)
                .build();

        return create(dto);
    }

    @Override
    @Transactional(readOnly = true)
    public List<ActionLogDto> getAll() {
        return actionLogMapper.toDtoList(actionLogRepository.findAllByOrderByCreatedAtDesc());
    }

    @Override
    @Transactional(readOnly = true)
    public List<ActionLogDto> getAllByRequestId(String requestId) {
        if (requestId == null || requestId.isBlank()) {
            return List.of();
        }
        return actionLogMapper.toDtoList(
                actionLogRepository.findAllByRequestIdOrderByCreatedAtDesc(requestId));
    }

    private String resolveCurrentUsername() {
        try {
            String username = currentUserService.getUsername();
            if (username != null && !username.isBlank()) {
                return username.trim();
            }
        } catch (Exception ignored) {
            // Fallback is used when request is executed outside user-authenticated context.
        }
        return "SYSTEM";
    }
}

