    private boolean isSplitAmountSumValid(CbrTransaction txn) {
        if (txn == null) {
            return true;
        }
        if (txn.getSettlementAmount() == null) {
            return false;
        }
        if (txn.getRegulatoryDetails() == null || txn.getRegulatoryDetails().isEmpty()) {
            return false;
        }
        java.math.BigDecimal sum = java.math.BigDecimal.ZERO;
        boolean hasSplitAmount = false;
        for (CbrTransactionStat stat : txn.getRegulatoryDetails()) {
            if (stat.getSplitAmount() != null) {
                hasSplitAmount = true;
                sum = sum.add(stat.getSplitAmount());
            }
        }
        if (!hasSplitAmount) {
            return false;
        }
        return sum.compareTo(txn.getSettlementAmount()) == 0;
    }

    private boolean isLoanFieldsValidForSplitStatCode(CbrTransaction txn) {
        if (txn == null) {
            return true;
        }
        if (txn.getRegulatoryDetails() == null || txn.getRegulatoryDetails().isEmpty()) {
            return true;
        }
        boolean requiresLoanFields = txn.getRegulatoryDetails().stream()
                .map(CbrTransactionStat::getSplitStatCode)
                .filter(Objects::nonNull)
                .map(String::trim)
                .anyMatch(LOAN_ALLOWED_SPLIT_STAT_CODES::contains);
        if (!requiresLoanFields) {
            return true;
        }
        return !isBlank(txn.getLoanYear()) && !isBlank(txn.getLoanNumber());
    }

