    private boolean matchesOriginalP8ReportType(
            CbrTransaction txn, String expectedReportType, TransferDirection direction, String validationNo) {
        if (txn == null) {
            return false;
        }
        if (isBlank(txn.getOriginalTransactionId())) {
            LOG.info("Validation {} skipped: missing originalTransactionId on txn id={}", validationNo, txn.getId());
            return false;
        }
        if (txn.getOriginalSettlementDate() == null) {
            LOG.info("Validation {} skipped: missing originalSettlementDate on txn id={}", validationNo, txn.getId());
            return false;
        }
        Optional<CbrTransaction> originalP8 = transactionRepository
                .findFirstByPaymentReferenceAndSettlementDateAndDirectionAndMessageType(
                        txn.getOriginalTransactionId(), txn.getOriginalSettlementDate(),
                        direction, MessageType.P8);
        if (originalP8.isEmpty()) {
            LOG.info("Validation {} skipped: no original P8 found (origTxId={}, origSettlDate={})",
                    validationNo, txn.getOriginalTransactionId(), txn.getOriginalSettlementDate());
            return false;
        }
        return expectedReportType.equalsIgnoreCase(originalP8.get().getReportType());
    }

    private String resolveRelatedFieldValue(CbrTransaction entity, TransferDirection direction, String fieldKey) {
        if (entity == null || direction == null) {
            return null;
        }
        Optional<CbrTransaction> related = findRelatedP8Transaction(entity, direction);
        if (related.isEmpty()) {
            return null;
        }
        if (isRelatedStatField(fieldKey)) {
            return resolveRelatedStatFieldValue(related.get(), fieldKey);
        }
        String relatedStatFieldValue = resolveRelatedStatFieldValue(related.get(), fieldKey);
        if (!isBlank(relatedStatFieldValue)) {
            return relatedStatFieldValue;
        }
        return resolveFieldValue(fieldKey, related.get());
    }

    private Optional<CbrTransaction> findRelatedP8Transaction(CbrTransaction entity, TransferDirection direction) {
        if (entity == null || direction == null) {
            return Optional.empty();
        }
        String originalTransactionId = entity.getOriginalTransactionId();
        if (isBlank(originalTransactionId)) {
            LOG.info("Related P8 lookup skipped: missing originalTransactionId on txn id={}", entity.getId());
            return Optional.empty();
        }
        if (entity.getOriginalSettlementDate() == null) {
            LOG.info("Related P8 lookup skipped: missing originalSettlementDate on txn id={}", entity.getId());
            return Optional.empty();
        }
        Optional<CbrTransaction> related = transactionRepository
                .findWithRegulatoryDetailsFirstByPaymentReferenceAndSettlementDateAndDirectionAndMessageType(
                        originalTransactionId, entity.getOriginalSettlementDate(), direction, MessageType.P8);
        if (related.isEmpty()) {
            LOG.info("Related P8 lookup: no related P8 txn found (origTxId={}, direction={})",
                    originalTransactionId, direction);
        }
        return related;
    }

    private boolean isRelatedStatField(String fieldKey) {
        if (isBlank(fieldKey)) {
            return false;
        }
        String normalizedFieldKey = fieldKey.trim().toUpperCase(java.util.Locale.ROOT);
        return "SPLIT_STAT_CODE".equals(normalizedFieldKey)
                || "SPLIT_AMOUNT".equals(normalizedFieldKey)
                || "INVOICE_NUMBER".equals(normalizedFieldKey)
                || "INVOICE_YEAR".equals(normalizedFieldKey);
    }

    private String resolveRelatedStatFieldValue(CbrTransaction relatedTxn, String fieldKey) {
        if (relatedTxn == null || isBlank(fieldKey)) {
            return null;
        }
        String normalizedFieldKey = fieldKey.trim().toUpperCase(java.util.Locale.ROOT);
        if (!isRelatedStatField(normalizedFieldKey)) {
            return null;
        }
        if (relatedTxn.getRegulatoryDetails() == null || relatedTxn.getRegulatoryDetails().isEmpty()) {
            return null;
        }

        if (relatedTxn.getRegulatoryDetails().size() > 1) {
            LOG.info(
                    "Related P8 txn id={} has {} regulatory detail rows; using the first row for field {}",
                    relatedTxn.getId(),
                    relatedTxn.getRegulatoryDetails().size(),
                    normalizedFieldKey);
        }

        CbrTransactionStat firstStat = relatedTxn.getRegulatoryDetails().get(0);
        return switch (normalizedFieldKey) {
            case "SPLIT_STAT_CODE" -> firstStat.getSplitStatCode();
            case "SPLIT_AMOUNT" -> firstStat.getSplitAmount() != null
                    ? firstStat.getSplitAmount().stripTrailingZeros().toPlainString()
                    : null;
            case "INVOICE_NUMBER" -> firstStat.getInvoiceNumber();
            case "INVOICE_YEAR" -> firstStat.getInvoiceYear();
            default -> null;
        };
    }
