package rs.unicredit.cbr.repository;

import java.util.List;
import java.util.Optional;

import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.transaction.annotation.Transactional;

import rs.unicredit.cbr.model.GlFeeData;

public interface GlFeeDataRepository extends JpaRepository<GlFeeData, Long> {

    Optional<GlFeeData> findByCallReplyRef(String callReplyRef);

    boolean existsByCallReplyRef(String callReplyRef);

    List<GlFeeData> findAllByBookingStatusOrderByIdAsc(String bookingStatus);

    List<GlFeeData> findAllByRequestIdOrderByIdAsc(Long requestId);

    @Transactional
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("""
            update GlFeeData g
               set g.fee = :fee,
                   g.narrative1 = :narrative1,
                   g.narrative2 = :narrative2,
                   g.bookingStatus = :nextStatus
             where g.id = :id
               and g.bookingStatus = :currentStatus
            """)
    int updateFeePreparationData(
            @Param("id") Long id,
            @Param("currentStatus") String currentStatus,
            @Param("nextStatus") String nextStatus,
            @Param("fee") java.math.BigDecimal fee,
            @Param("narrative1") String narrative1,
            @Param("narrative2") String narrative2);

    @Transactional
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("""
            update GlFeeData g
               set g.bookingStatus = :nextStatus
             where g.id = :id
               and g.bookingStatus = :currentStatus
            """)
    int updateBookingStatus(
            @Param("id") Long id,
            @Param("currentStatus") String currentStatus,
            @Param("nextStatus") String nextStatus);

    @Transactional
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("""
            update GlFeeData g
               set g.opu = :opu,
                   g.amount = :amount,
                   g.amountRsd = :amountRsd,
                   g.creditAccount = :creditAccount,
                   g.middrate = :middrate,
                   g.bookingStatus = :nextStatus
             where g.id = :id
               and g.bookingStatus = :currentStatus
            """)
    int updateEnrichmentResult(
            @Param("id") Long id,
            @Param("currentStatus") String currentStatus,
            @Param("nextStatus") String nextStatus,
            @Param("opu") String opu,
            @Param("amount") java.math.BigDecimal amount,
            @Param("amountRsd") java.math.BigDecimal amountRsd,
            @Param("creditAccount") Long creditAccount,
            @Param("middrate") java.math.BigDecimal middrate);
}

