  const configurableColumnSet = useMemo(
    () => new Set(availableColumnKeys),
    [availableColumnKeys]
  );
  const frozenColumnSet = useMemo(
    () => new Set(frozenColumnKeys),
    [frozenColumnKeys]
  );
  const columnsById = useMemo(
    () =>
      new Map(
        normalizedColumns.map((column) => [normalizeColumnId(column), column])
      ),
    [normalizedColumns]
  );
  const visibleColumns = useMemo(() => {
    if (!configurableColumns.length) return normalizedColumns;

    const firstConfigurableIndex = normalizedColumns.findIndex((column) =>
      configurableColumnSet.has(normalizeColumnId(column))
    );
    const nonConfigurableBefore =
      firstConfigurableIndex > 0
        ? normalizedColumns
            .slice(0, firstConfigurableIndex)
            .filter(
              (column) =>
                !configurableColumnSet.has(normalizeColumnId(column))
            )
        : [];
    const nonConfigurableAfter = normalizedColumns
      .slice(firstConfigurableIndex < 0 ? 0 : firstConfigurableIndex)
      .filter(
        (column) => !configurableColumnSet.has(normalizeColumnId(column))
      );

    const orderedVisibleConfigurableKeys = columnOrderKeys.filter(
      (key) => selectedColumnSet.has(key) && configurableColumnSet.has(key)
    );
    const frozenOrderedKeys = orderedVisibleConfigurableKeys.filter((key) =>
      frozenColumnSet.has(key)
    );
    const nonFrozenOrderedKeys = orderedVisibleConfigurableKeys.filter(
      (key) => !frozenColumnSet.has(key)
    );
    const orderedVisibleConfigurable = [...frozenOrderedKeys, ...nonFrozenOrderedKeys]
      .map((key) => {
        const column = columnsById.get(key);
        if (!column) return null;
        const fixedValue = column?.fixed;
        const isFixedLeft = fixedValue === "left" || fixedValue === true;
        const isFixedRight = fixedValue === "right";

        if (frozenColumnSet.has(key)) {
          if (isFixedRight) return column;
          return { ...column, fixed: "left" };
        }

        if (isFixedLeft) {
          return { ...column, fixed: undefined };
        }

        return column;
      })
      .filter(Boolean);

    return [
      ...nonConfigurableBefore,
      ...orderedVisibleConfigurable,
      ...nonConfigurableAfter,
    ];
  }, [
    columnOrderKeys,
    columnsById,
    configurableColumnSet,
    configurableColumns.length,
    frozenColumnSet,
    normalizedColumns,
    selectedColumnSet,
  ]);

  const horizontalScrollWidth = useMemo(
    () =>
      visibleColumns.reduce((totalWidth, column) => {
        const numericWidth = Number(column?.width);
        if (Number.isFinite(numericWidth) && numericWidth > 0) {
          return totalWidth + numericWidth;
        }
        return totalWidth + MIN_TABLE_COLUMN_WIDTH;
      }, 0),
    [visibleColumns]
  );

  useEffect(() => {
    if (typeof window === "undefined") return undefined;

    const tableViewportElement = tableViewportRef.current;
    const scrollContainer =
      tableViewportElement?.querySelector(".ant-table-content") ||
      tableViewportElement?.querySelector(".ant-table-body") ||
      null;

    if (!tableViewportElement || !scrollContainer) {
      return undefined;
    }

    const syncHorizontalShiftState = () => {
      if (scrollContainer.scrollLeft > 0) {
        tableViewportElement.dataset.horizontalShifted = "true";
      } else {
        delete tableViewportElement.dataset.horizontalShifted;
      }
    };

    syncHorizontalShiftState();
    scrollContainer.addEventListener("scroll", syncHorizontalShiftState, {
      passive: true,
    });

    return () => {
      scrollContainer.removeEventListener("scroll", syncHorizontalShiftState);
      delete tableViewportElement.dataset.horizontalShifted;
    };
  }, [dataSource.length, loading, visibleColumns.length]);

  const openColumnsModal = () => {
    onChangeColumns?.();
    setDraftSelectedColumnKeys(selectedColumnKeys);
    setDraftColumnOrderKeys(columnOrderKeys);
    setDraftFrozenColumnKeys(frozenColumnKeys);
    setIsColumnsModalOpen(true);
  };

  const openArchiveSearchModal = () => {
    if (!canSearchArchive) return;
    setIsArchiveSearchModalOpen(true);
  };

  const closeColumnsModal = () => {
    setDraftSelectedColumnKeys(selectedColumnKeys);
    setDraftColumnOrderKeys(columnOrderKeys);
    setDraftFrozenColumnKeys(frozenColumnKeys);
    setIsColumnsModalOpen(false);
  };

  const closeArchiveSearchModal = () => {
    if (loading) return;
    setIsArchiveSearchModalOpen(false);
  };

  const handleReloadClick = () => {
    if (!canReload) return;
    onReload();
  };

  const saveColumnsSelection = () => {
    const availableSet = new Set(availableColumnKeys);
    const nextOrder = [
      ...draftColumnOrderKeys.filter((key) => availableSet.has(key)),
      ...availableColumnKeys.filter(
        (key) => !draftColumnOrderKeys.includes(key)
      ),
    ];
    const normalizedVisible = draftSelectedColumnKeys.filter((key) =>
      availableSet.has(key)
    );
    const nextVisibleBase = normalizedVisible.length
      ? normalizedVisible
      : defaultVisibleColumnKeys;
    const nextFrozen = draftFrozenColumnKeys
      .filter((key) => availableSet.has(key))
      .slice(0, MAX_FROZEN_COLUMN_KEYS);
    const nextVisible = Array.from(new Set([...nextVisibleBase, ...nextFrozen]));

    setSelectedColumnKeys(nextVisible);
    setColumnOrderKeys(nextOrder);
    setFrozenColumnKeys(nextFrozen);
    setSessionStorageItem(
      effectiveStorageKey,
      JSON.stringify({ visible: nextVisible, order: nextOrder, frozen: nextFrozen })
    );
    setIsColumnsModalOpen(false);
  };

  const exportColumns = useMemo(
    () =>
      columnOrderKeys
        .filter(
          (columnKey) =>
            selectedColumnSet.has(columnKey) &&
            configurableColumnSet.has(columnKey)
        )
        .map((columnKey, index) => {
          const column = columnsById.get(columnKey);
          if (!column) return null;
          return {
            key: columnKey,
            title: getColumnLabel(column),
            order: index,
          };
        })
        .filter(Boolean),
    [columnOrderKeys, columnsById, configurableColumnSet, selectedColumnSet]
  );

  const exportTransactionIds = useMemo(
    () =>
      tableDataForExport
        .map((record) => {
          if (typeof rowKey === "function") {
            return rowKey(record);
          }
          if (typeof rowKey === "string" && rowKey) {
            return record?.[rowKey];
          }
          return record?.id;
        })
        .map(toTransactionId)
        .filter((value) => value !== null),
    [rowKey, tableDataForExport]
  );

  const handleExportClick = async () => {
    const payload = {
      transactionIds: exportTransactionIds,
      columns: exportColumns,
    };

    if (!payload.transactionIds.length) {
      message.warning(
        t("common:exportNoRows", {
          defaultValue: "Nema transakcija za izvoz.",
        })
      );
      return;
    }

    if (!payload.columns.length) {
      message.warning(
        t("common:exportNoColumns", {
          defaultValue: "Nema kolona za izvoz.",
        })
      );
      return;
    }

    if (typeof onExport === "function") {
      await onExport(payload);
      return;
    }

    setIsExporting(true);
    try {
      const response = await exportTransactionsExcel(payload);
      const contentDisposition = response?.headers?.["content-disposition"];
      const fileName =
        parseFileNameFromContentDisposition(contentDisposition) ||
        "transactions.xlsx";
      const contentType =
        response?.headers?.["content-type"] ||
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
      const fileBlob = new Blob([response?.data], { type: contentType });
      triggerFileDownload(fileBlob, fileName);
    } catch (error) {
      message.error(
        t("common:exportFailed", {
          defaultValue: "Neuspesan izvoz u Excel.",
        })
      );
    } finally {
      setIsExporting(false);
    }
  };

  const handleTableChange = (nextPagination, _, __, extra) => {
    setPaginationState((prev) => {
      const nextCurrent = nextPagination?.current ?? prev.current;
      const nextPageSize = nextPagination?.pageSize ?? prev.pageSize;
      if (nextCurrent === prev.current && nextPageSize === prev.pageSize) {
        return prev;
      }
      return {
        current: nextCurrent,
        pageSize: nextPageSize,
      };
    });

    if (Array.isArray(extra?.currentDataSource)) {
      setTableDataForExport(extra.currentDataSource);
      return;
    }
    setTableDataForExport(dataSource);
  };

  const handleArchiveSearchFieldChange = (field, value) => {
    setArchiveSearchFilters((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleArchiveSearchSubmit = async () => {
    if (!canSearchArchive || loading) return;

    const receivedDateFrom = toPickerDate(archiveSearchFilters.receivedDateFrom);
    const receivedDateTo = toPickerDate(archiveSearchFilters.receivedDateTo);

    if (receivedDateFrom && receivedDateTo) {
      if (receivedDateFrom.getTime() > receivedDateTo.getTime()) {
        message.error(
          t("common:archiveSearchInvalidRange", {
            defaultValue: 'Polje "Datum prijema (od)" mora biti manje ili jednako polju "Datum prijema (do)".',
          })
        );
        return;
      }

      if (receivedDateTo.getTime() > addMonths(receivedDateFrom, 6).getTime()) {
        message.error(
          t("common:archiveSearchRangeLimit", {
            defaultValue:
              'Period izmedju polja "Datum prijema (od)" i "Datum prijema (do)" ne sme biti duzi od 6 meseci.',
          })
        );
        return;
      }
    }

    try {
      const searchResult = await onArchiveSearch(
        buildArchiveSearchPayload(archiveSearchFilters)
      );
      if (searchResult !== false) {
        setIsArchiveSearchModalOpen(false);
      }
    } catch (error) {
      // Parent handles user-facing error state.
    }
  };

  return (
    <section
      className={`${styles.wrapper} ${className}`.trim()}
      data-transaction-tone={transactionTone}
    >
      {showToolbar ? (
        <div className={styles.toolbar}>
          <SearchData
            value={searchQuery}
            onChange={setSearchQuery}
            placeholder={t("common:search", { defaultValue: "Pretraga" })}
            tooltip={searchTooltip}
          />
          <div className={styles.toolbarActions}>
            {canReload ? (
              <Tooltip title={t("common:reload", { defaultValue: "Reload" })}>
                <Button
                  type="default"
                  className={`${styles.toolbarButton} ${styles.toolbarIconButton}`}
                  icon={<ReloadOutlined />}
                  onClick={handleReloadClick}
                  disabled={loading}
                />
              </Tooltip>
            ) : null}
            <Button
              type="default"
              className={styles.toolbarButton}
              icon={<AppstoreOutlined />}
              onClick={openColumnsModal}
              disabled={!configurableColumns.length}
            >
              {t("common:changeColumns", {
                defaultValue: "Change columns",
              })}
            </Button>
            <Button
              type="default"
              className={styles.toolbarButton}
              icon={<DownloadOutlined />}
              onClick={handleExportClick}
              loading={isExporting}
              disabled={
                isExporting ||
                exportColumns.length === 0 ||
                exportTransactionIds.length === 0
              }
            >
              {t("common:exportExcel", { defaultValue: "Export Excel" })}
            </Button>
            {canSearchArchive ? (
              <Button
                type="default"
                className={styles.toolbarButton}
                icon={<SearchOutlined />}
                onClick={openArchiveSearchModal}
                disabled={loading}
              >
                {t("common:archiveSearch", { defaultValue: "Pretraga arhive" })}
              </Button>
            ) : null}
          </div>
        </div>
      ) : null}

      <div ref={tableViewportRef} className={styles.tableViewport}>
        <Table
          className={styles.table}
          columns={visibleColumns}
          dataSource={dataSource}
          loading={loading}
          rowKey={rowKey}
          onChange={handleTableChange}
          onRow={
            typeof onView === "function"
              ? (record) => ({
                  onDoubleClick: () => onView(record),
                })
              : undefined
          }
          scroll={{ x: horizontalScrollWidth }}
          tableLayout="fixed"
          showSorterTooltip={false}
          pagination={{
            current: paginationState.current,
            pageSize: paginationState.pageSize,
            size: "small",
            showSizeChanger: true,
            pageSizeOptions: ["10", "20", "50"],
          }}
        />
      </div>

      <ChangeColumnsModal
        t={t}
        open={isColumnsModalOpen}
        onCancel={closeColumnsModal}
        onOk={saveColumnsSelection}
        columnsById={columnsById}
        configurableColumnSet={configurableColumnSet}
        defaultVisibleColumnKeys={defaultVisibleColumnKeys}
        draftSelectedColumnKeys={draftSelectedColumnKeys}
        setDraftSelectedColumnKeys={setDraftSelectedColumnKeys}
        draftColumnOrderKeys={draftColumnOrderKeys}
        setDraftColumnOrderKeys={setDraftColumnOrderKeys}
        draftFrozenColumnKeys={draftFrozenColumnKeys}
        setDraftFrozenColumnKeys={setDraftFrozenColumnKeys}
        maxFrozenColumnKeys={MAX_FROZEN_COLUMN_KEYS}
      />

      <ArchiveSearchModal
        t={t}
        open={isArchiveSearchModalOpen}
        onCancel={closeArchiveSearchModal}
        onOk={handleArchiveSearchSubmit}
        loading={loading}
        filters={archiveSearchFilters}
        onChangeField={handleArchiveSearchFieldChange}
      />
    </section>
  );
};

export default withTranslation(["common", "columns"])(DataTable);

