const resolvePageTitle = (pathname, t) => {
  const match = ROUTE_TITLES.find((route) =>
    matchPath({ path: route.path, end: false }, pathname)
  );
  if (!match) return "";
  return t(match.key, { defaultValue: match.fallback });
};

const PageTitleManager = () => {
  const location = useLocation();
  const { t, i18n } = useTranslation(["common", "sidebar"]);
  const [sidebarTitle, setSidebarTitle] = useState("");

  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const handler = (event) => {
      setSidebarTitle(event?.detail || "");
    };
    window.addEventListener("sidebar-title-change", handler);
    return () => {
      window.removeEventListener("sidebar-title-change", handler);
    };
  }, []);

  useEffect(() => {
    const appTitle = t("common:appTitle", {
      defaultValue: "CB reporting - SEPA",
    });
    const pageTitle = sidebarTitle || resolvePageTitle(location.pathname, t);
    document.title = pageTitle ? `${pageTitle} | ${appTitle}` : appTitle;
  }, [location.pathname, t, i18n.language, sidebarTitle]);

  return null;
};

export default PageTitleManager;

