import React, { useEffect, useMemo, useState } from "react";
import { NavLink } from "react-router-dom";
import { Menu as AntMenu } from "antd";
import { HomeOutlined } from "@ant-design/icons";
import styles from "./Menu.module.css";

const getOpenKeys = (items, selectedKey) => {
  if (!selectedKey) return [];
  for (const item of items) {
    const key = item.key || item.title;
    if (item.children?.length) {
      const hasSelected = item.children.some(
        (child) => (child.key || child.title) === selectedKey
      );
      if (hasSelected) return [key];
    }
  }
  return [];
};

const Menu = ({ items, selectedKey, animateKey }) => {
  const menuClassName = styles.menu;
  const mode = "inline";
  const [openKeys, setOpenKeys] = useState(() =>
    getOpenKeys(items, selectedKey)
  );

  useEffect(() => {
    setOpenKeys(getOpenKeys(items, selectedKey));
  }, [items, selectedKey]);

  const renderContent = (item, { showIcon = true } = {}) => (
    <>
      {showIcon && (
        <span className={styles.menuIcon}>
          {item.icon || <HomeOutlined />}
        </span>
      )}
      <span className={styles.menuText}>{item.title}</span>
    </>
  );

  const resolveLabelClassName = (item) =>
    item.labelClassName
      ? styles[item.labelClassName] || item.labelClassName
      : "";

  const renderLabel = (item, options) => {
    const labelClassName = resolveLabelClassName(item);
    return (
      <div
        className={`${styles.menuLink} ${labelClassName}`.trim()}
        aria-disabled={item.path ? undefined : "true"}
      >
        {renderContent(item, options)}
      </div>
    );
  };

  const menuItems = useMemo(() => {
    const buildItems = (list, parentKey, depth = 0) =>
      list.map((item) => {
        const key = item.key || item.title || parentKey;
        const showIcon = depth === 0;
        const labelClassName = resolveLabelClassName(item);
        const label = item.path ? (
          <NavLink
            to={item.path}
            className={`${styles.menuLink} ${labelClassName}`.trim()}
          >
            {renderContent(item, { showIcon })}
          </NavLink>
        ) : (
          renderLabel(item, { showIcon })
        );

        if (item.children?.length) {
          return {
            key,
            label,
            children: buildItems(item.children, key, depth + 1),
          };
        }

        return {
          key,
          label,
          disabled: !item.path,
        };
      });

    return buildItems(items);
  }, [items]);

  return (
    <nav
      key={animateKey}
      className={`${styles.menuSection} ${styles.menuAnimated}`}
      aria-label="Primary"
    >
      <AntMenu
        className={menuClassName}
        mode={mode}
        theme="dark"
        selectedKeys={selectedKey ? [selectedKey] : []}
        openKeys={openKeys}
        onOpenChange={setOpenKeys}
        items={menuItems}
      />
    </nav>
  );
};

export default Menu;

