import React, { useMemo, useState, useEffect } from "react";
import { withTranslation } from "react-i18next";
import { useLocation, useNavigate } from "react-router-dom";
import { Avatar, Layout, Typography } from "antd";
import getMenuItems from "./menu/menuItems";
import KeyCloakService from "../../security/KeycloakService";
import styles from "./Sidebar.module.css";
import TransactionTypeSelect from "./transactions/TransactionTypeSelect";
import Menu from "./menu/Menu";
import SidebarFooter from "./footer/SidebarFooter";
import { getDisplayName } from "../../security/jwtUtil";
import {
  ALL_ORDERS,
  COMPLAINTS,
  DASHBOARD,
  INCOMING,
  OUTGOING,
} from "../../components/routes";

const getInitials = (fullName) => {
  if (!fullName) return "";
  return fullName
    .split(" ")
    .map((part) => part.trim())
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0].toUpperCase())
    .join("");
};

const Sidebar = ({ t }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [transactionType, setTransactionType] = useState("outgoing");

  useEffect(() => {
    if (location.pathname.startsWith(INCOMING)) {
      setTransactionType("incoming");
    } else if (location.pathname.startsWith(OUTGOING)) {
      setTransactionType("outgoing");
    } else if (location.pathname.startsWith(COMPLAINTS)) {
      setTransactionType("complaints");
    } else if (location.pathname.startsWith(ALL_ORDERS)) {
      setTransactionType("allOrders");
    } else if (location.pathname.startsWith(DASHBOARD)) {
      setTransactionType("outgoing");
    }
  }, [location.pathname]);
  const menuItems = useMemo(() => {
    const menuSets = getMenuItems(t);
    const transactionMenuConfig =
      menuSets[`${transactionType}Items`] || menuSets.incomingItems || [];
    const menuConfig = [
      ...transactionMenuConfig,
      ...(menuSets.bookingFeeItems || []),
    ];

    return menuConfig
      .filter((item) => KeyCloakService.isAuthorized(item.role))
      .map((item) => {
        if (!item.children?.length) return item;
        const children = item.children.filter((subItem) =>
          KeyCloakService.isAuthorized(subItem.role)
        );
        return { ...item, children };
      });
  }, [t, transactionType]);

  let displayName = "User";
  try {
    displayName = getDisplayName() || KeyCloakService.getUsername() || "User";
  } catch (error) {
    displayName = "User";
  }
  const initials = getInitials(displayName) || "U";

  const handleLogout = () => {
    KeyCloakService.logoutUser();
  };

  const bestMatch = useMemo(() => {
    let match = null;
    const consider = (entry, key) => {
      if (!entry?.path) return;
      if (!location.pathname.startsWith(entry.path)) return;
      if (!match || entry.path.length > match.path.length) {
        match = { key, title: entry.title || "", path: entry.path };
      }
    };

    for (const item of menuItems) {
      const itemKey = item.key || item.title;
      consider(item, itemKey);
      if (item.children?.length) {
        for (const child of item.children) {
          const childKey = child.key || child.title;
          consider(child, childKey);
        }
      }
    }

    return match;
  }, [menuItems, location.pathname]);

  const selectedKey =
    bestMatch?.key ||
    (transactionType === "complaints"
      ? "complaints-all-orders"
      : transactionType === "allOrders"
      ? "all-orders-all-orders"
      : "");
  const activeTitle = bestMatch?.title || "";

  useEffect(() => {
    if (typeof document !== "undefined") {
      if (activeTitle) {
        document.body.dataset.sidebarTitle = activeTitle;
      } else {
        delete document.body.dataset.sidebarTitle;
      }
    }
    if (typeof window !== "undefined") {
      window.dispatchEvent(
        new CustomEvent("sidebar-title-change", { detail: activeTitle || "" })
      );
    }
  }, [activeTitle]);

  useEffect(() => {
    return () => {
      if (typeof document !== "undefined") {
        delete document.body.dataset.sidebarTitle;
      }
      if (typeof window !== "undefined") {
        window.dispatchEvent(
          new CustomEvent("sidebar-title-change", { detail: "" })
        );
      }
    };
  }, []);

  const handleTransactionChange = (nextValue) => {
    setTransactionType(nextValue);
    if (nextValue === "incoming") {
      if (!location.pathname.startsWith(INCOMING)) {
        navigate(INCOMING);
      }
    } else if (nextValue === "outgoing") {
      if (!location.pathname.startsWith(OUTGOING)) {
        navigate(OUTGOING);
      }
    } else if (nextValue === "complaints") {
      if (!location.pathname.startsWith(COMPLAINTS)) {
        navigate(COMPLAINTS);
      }
    } else if (nextValue === "allOrders") {
      if (!location.pathname.startsWith(ALL_ORDERS)) {
        navigate(ALL_ORDERS);
      }
    }
  };

  return (
    // Frame 1438 (node 786:8488): Sidebar (desktop layout)
    <Layout.Sider width={247} className={styles.sidebar} theme="dark">
      <div className={styles.topSection}>
        {/* Frame 510 (node 786:8489): Header + filter */}
        <div className={styles.brandBlock}>
          <div className={styles.brandRow}>
            <Avatar
              shape="square"
              size={28}
              className={styles.brandAvatar}
            >
              S
            </Avatar>
            <Typography.Text className={styles.brandTitle}>
              CBR App
            </Typography.Text>
          </div>

          <TransactionTypeSelect
            t={t}
            value={transactionType}
            onChange={handleTransactionChange}
          />
        </div>

        <Menu
          items={menuItems}
          selectedKey={selectedKey}
          animateKey={transactionType}
        />
      </div>

      {/* Frame 547 (node 786:8509): Logout segment */}
      <SidebarFooter
        t={t}
        displayName={displayName}
        initials={initials}
        onLogout={handleLogout}
      />
    </Layout.Sider>
  );
};

