// Mount function to start up the app
const mount = (el, { onNavigate, defaultHistory, initialPath }) => {
  let resizeObserver = null;
  let frameId = null;

  const syncHostSize = () => {
    if (!el || typeof window === "undefined") {
      return;
    }

    const rect = el.getBoundingClientRect();
    const leftOffset = Number.isFinite(rect.left) ? Math.max(rect.left, 0) : 0;
    const availableWidth = Math.max(window.innerWidth - leftOffset, 0);

    el.style.width = `${availableWidth}px`;
    el.style.maxWidth = `${availableWidth}px`;
    el.style.height = "100%";
    el.style.minWidth = "0";
    el.style.minHeight = "0";
    el.style.display = "block";
    el.style.flex = "1 1 0%";
    el.style.boxSizing = "border-box";
    el.style.overflow = "hidden";
  };

  if (el) {
    syncHostSize();

    if (typeof window !== "undefined") {
      const handleResize = () => {
        if (frameId !== null) {
          window.cancelAnimationFrame(frameId);
        }
        frameId = window.requestAnimationFrame(() => {
          syncHostSize();
        });
      };

      window.addEventListener("resize", handleResize);

      if (typeof ResizeObserver !== "undefined") {
        resizeObserver = new ResizeObserver(() => {
          handleResize();
        });

        if (el.parentElement) {
          resizeObserver.observe(el.parentElement);
        }
      }

      el.__cbrCleanup = () => {
        window.removeEventListener("resize", handleResize);
        if (frameId !== null) {
          window.cancelAnimationFrame(frameId);
          frameId = null;
        }
        if (resizeObserver) {
          resizeObserver.disconnect();
          resizeObserver = null;
        }
      };
    }
  }

  const history =
    defaultHistory ||
    createMemoryHistory({
      initialEntries: [initialPath],
    });

  if (onNavigate) {
    history.listen(onNavigate);
  }

  const root = ReactDOM.createRoot(el);
  const renderApp = () => root.render(<App history={history} />);

  if (process.env.ENV_START_TYPE === "isolation")
    KeycloakService.loginUser(renderApp);
  else renderApp();

  return {
    onParentNavigate({ pathname: nextPathname }) {
      const { pathname } = history.location;
      if (pathname !== nextPathname) {
        history.push(nextPathname);
      }
    },
  };
};

