    private CbrTransactionArchive findOutgoingArchiveTransaction(Long transactionId) {
        return cbrTransactionArchiveRepository.findWithRegulatoryDetailsById(transactionId)
                .filter(this::isOutgoingDirection)
                .orElseThrow(() -> new ResponseStatusException(
