        if (!cancelled) {
          setNotes(apiNotes.map((entry, index) => mapNoteEntry(entry, index)));
        }
      } catch (error) {
        if (!cancelled) {
          setNotes(fallbackNotes);
          Notification(
            "Greska",
            "Neuspesno ucitavanje beleski.",
            "error",
            "topRight"
          );
        }
      }
    };

    loadNotes();

    return () => {
      cancelled = true;
    };
  }, [fallbackNotes, open, transactionId]);

  useEffect(() => {
    let cancelled = false;

    const loadHistoryEntries = async () => {
      if (!open) return;

      if (!transactionId) {
        setHistoryEntries(fallbackHistoryEntries);
        return;
      }

      if (!transactionApi?.getActionLog) {
        setHistoryEntries(fallbackHistoryEntries);
        return;
      }

      try {
        const response = await transactionApi.getActionLog(transactionId);
        const apiHistory = Array.isArray(response?.data) ? response.data : [];

        if (!cancelled) {
          if (apiHistory.length > 0) {
            setHistoryEntries(apiHistory.map((entry, index) => mapHistoryEntry(entry, index)));
          } else {
            setHistoryEntries(fallbackHistoryEntries);
          }
        }
      } catch (error) {
        if (!cancelled) {
          setHistoryEntries(fallbackHistoryEntries);
        }
      }
    };

    loadHistoryEntries();

    return () => {
      cancelled = true;
    };
  }, [fallbackHistoryEntries, open, transactionApi, transactionId]);

  useEffect(() => {
    let cancelled = false;

    const loadManualErrors = async () => {
      if (!open) {
        return;
      }

      if (!MANUAL_VALIDATION_STATUS_CODES.has(transactionStatusCode)) {
        setManualValidationErrors([]);
        return;
      }

      if (!isPresent(transactionId)) {
        setManualValidationErrors([]);
        return;
      }

      if (!transactionApi?.getManualValidationErrors) {
        setManualValidationErrors([]);
        return;
      }

      try {
        const response = await transactionApi.getManualValidationErrors(transactionId);
        if (!cancelled) {
          setManualValidationErrors(mapManualValidationErrors(response?.data));
        }
      } catch (error) {
        if (!cancelled) {
          setManualValidationErrors([]);
        }
      }
    };

    loadManualErrors();

    return () => {
      cancelled = true;
    };
  }, [open, transactionStatusCode, transactionApi, transactionId]);

  const handleAddNote = async (description) => {
    if (!canModifyData) {
      Notification(
        t("common:errorTitle", { defaultValue: "Greska" }),
        t("common:actionNotAllowed", {
          defaultValue: "Nemate privilegije za ovu akciju.",
        }),
        "error",
        "topRight"
      );
      return false;
    }

    if (!transactionId) {
      Notification(
        "Greska",
        "Nije moguce sacuvati belesku bez transaction ID.",
        "error",
        "topRight"
      );
      return false;
    }

    if (lockRequired && (isLockLoading || isLockBlocked)) {
      Notification(
        t("common:errorTitle", { defaultValue: "Greska" }),
        t("common:transactionLockedActive", {
          defaultValue: "Transakcija je zakljucana za izmenu.",
        }),
        "error",
        "topRight"
      );
      return false;
    }

    setIsSavingNote(true);
    try {
      const response = await createNotice({
        transactionId,
        description,
      });
      const savedNote = mapNoteEntry(response?.data, 0);
      setNotes((current) => [savedNote, ...current]);
      Notification("Uspeh", "Beleska je sacuvana.", "success", "topRight");
      return true;
    } catch (error) {
      Notification("Greska", "Neuspesno snimanje beleske.", "error", "topRight");
      return false;
    } finally {
      setIsSavingNote(false);
    }
  };

  const notifyActionNotAllowed = useCallback(() => {
    Notification(
      t("common:errorTitle", { defaultValue: "Greska" }),
      t("common:actionNotAllowed", {
        defaultValue: "Nemate privilegije za ovu akciju.",
      }),
      "error",
      "topRight"
    );
  }, [t]);

  const notifyLocalValidationFailed = useCallback(() => {
    Notification(
      t("common:manualEntryLocalValidationTitle", {
        defaultValue: "Validacija nije uspesna",
      }),
      t("common:manualEntryLocalValidationMessage", {
        defaultValue: "Ispravite validacione greske i pokusajte ponovo.",
      }),
      "error",
      "topRight"
    );
  }, [t]);

  const runTransactionAction = async (
    actionKey,
    actionFn,
    successMessage,
    nextStatusCode = null
  ) => {
    if (!canRunTransactionActions) {
      Notification(
        "Greska",
        "Akcija nije dostupna za odabrani nalog.",
        "error",
        "topRight"
      );
      return false;
