  const nextIndex = index + direction;
  if (index < 0 || nextIndex < 0 || nextIndex >= array.length) return array;
  const next = [...array];
  const [item] = next.splice(index, 1);
  next.splice(nextIndex, 0, item);
  return next;
};

const swapItems = (array, leftValue, rightValue) => {
  const leftIndex = array.indexOf(leftValue);
  const rightIndex = array.indexOf(rightValue);
  if (leftIndex < 0 || rightIndex < 0 || leftIndex === rightIndex) return array;
  const next = [...array];
  next[leftIndex] = rightValue;
  next[rightIndex] = leftValue;
  return next;
};

