package rs.unicredit.cbr.service;

import java.util.concurrent.atomic.AtomicBoolean;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@ConditionalOnBean(GlFeePrepareDataService.class)
@ConditionalOnProperty(prefix = "customs.fee-booking.enrich-new", name = "enabled", havingValue = "true")
public class GlFeeEnrichmentScheduler {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeEnrichmentScheduler.class);

    private final GlFeeEnrichmentService glFeeEnrichmentService;
    private final AtomicBoolean running = new AtomicBoolean(false);

    @Scheduled(fixedDelayString = "${customs.fee-booking.enrich-new.fixed-delay-ms:60000}")
    public void enrichNewFeeRows() {
        if (!running.compareAndSet(false, true)) {
            LOG.info("Skipping GL fee enrichment scheduler because previous run is still in progress.");
            return;
        }
        try {
            int enriched = glFeeEnrichmentService.enrichNewRows();
            LOG.info("GL fee enrichment scheduler finished enriched={}", enriched);
        } catch (Exception ex) {
            LOG.error("GL fee enrichment scheduler failed: {}", ex.getMessage(), ex);
        } finally {
            running.set(false);
        }
    }
}

