package rs.unicredit.cbr.service;

import java.math.BigDecimal;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.List;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import rs.unicredit.cbr.config.GlFeeBookingPreparationProperties;
import rs.unicredit.cbr.dto.GlBookingRequest;
import rs.unicredit.cbr.dto.GlBookingResponse;
import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.model.GlFeeBookingLog;
import rs.unicredit.cbr.repository.GlFeeBookingLogRepository;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
public class GlFeeBookingExecutionService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeBookingExecutionService.class);
    private static final String STATUS_PREPARED = "PREPARED";
    private static final String STATUS_BOOKED = "BOOKED";
    private static final String STATUS_BOOKING_ERROR = "BOOKING_ERROR";
    private static final String DEFAULT_CURRENCY = "44";
    private static final String DEFAULT_ORIGIN_CODE = "OV0";
    private static final int MAX_ERROR_MESSAGE_LENGTH = 1000;

    private final GlFeeBookingPreparationProperties glFeeBookingPreparationProperties;
    private final GlFeeDataRepository glFeeDataRepository;
    private final GlFeeBookingLogRepository glFeeBookingLogRepository;
    private final GlBookingService glBookingService;

    public GlBookingResponse executePrepared(String callReplyRef) {
        return executeForStatus(callReplyRef, STATUS_PREPARED);
    }

    public GlBookingResponse retryBookingError(String callReplyRef) {
        return executeForStatus(callReplyRef, STATUS_BOOKING_ERROR);
    }

    private GlBookingResponse executeForStatus(String callReplyRef, String expectedStatus) {
        String normalizedCallReplyRef = normalize(callReplyRef);
        if (normalizedCallReplyRef == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "callReplyRef is required");
        }

        GlFeeData feeData = glFeeDataRepository.findByCallReplyRef(normalizedCallReplyRef)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "GL fee data not found for callReplyRef=" + normalizedCallReplyRef));

        if (!expectedStatus.equalsIgnoreCase(normalize(feeData.getBookingStatus()))) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "GL fee data is not in " + expectedStatus + " status for callReplyRef=" + normalizedCallReplyRef
                            + ", currentStatus=" + feeData.getBookingStatus());
        }

        validatePreparedFeeData(feeData);
        GlBookingRequest request = buildRequest(feeData);
        String requestXml = glBookingService.buildMinimalRequestXml(request);
        LocalDateTime requestTime = LocalDateTime.now();
        String referenceNumber = feeData.getCallReplyRef();

        try {
            GlBookingResponse response = glBookingService.enterGlDealEntryMinimal(request);
            LocalDateTime responseTime = LocalDateTime.now();
            saveBookingLog(feeData, referenceNumber, requestTime, responseTime, requestXml, response, null);
            if (Boolean.TRUE.equals(response.getSuccess())) {
                int updated = glFeeDataRepository.updateBookingStatus(feeData.getId(), expectedStatus, STATUS_BOOKED);
                if (updated == 0) {
                    throw new ResponseStatusException(
                            HttpStatus.INTERNAL_SERVER_ERROR,
                            "GL booking succeeded but failed to mark BOOKED for callReplyRef=" + normalizedCallReplyRef);
                }
                LOG.info(
                        "GL fee booking success feeDataId={} requestId={} callReplyRef={} nextStatus={} transactionDealNumber={} reversalDealNumber={}",
                        feeData.getId(),
                        feeData.getRequestId(),
                        feeData.getCallReplyRef(),
                        STATUS_BOOKED,
                        response.getTransactionDealNumber(),
                        response.getReversalDealNumber());
                return response;
            }

            glFeeDataRepository.updateBookingStatus(feeData.getId(), expectedStatus, STATUS_BOOKING_ERROR);
            throw new ResponseStatusException(
                    HttpStatus.BAD_GATEWAY,
                    "GL booking returned unsuccessful response for callReplyRef=" + normalizedCallReplyRef
                            + ", returnCode=" + response.getReturnCode()
                            + ", resultCode=" + response.getResultCode());
        } catch (ResponseStatusException ex) {
            throw ex;
        } catch (Exception ex) {
            LocalDateTime responseTime = LocalDateTime.now();
            saveBookingLog(feeData, referenceNumber, requestTime, responseTime, requestXml, null, ex);
            glFeeDataRepository.updateBookingStatus(feeData.getId(), expectedStatus, STATUS_BOOKING_ERROR);
            throw new ResponseStatusException(
                    HttpStatus.BAD_GATEWAY,
                    "GL booking execution failed for callReplyRef=" + normalizedCallReplyRef + ": " + ex.getMessage(),
                    ex);
        }
    }

    private void validatePreparedFeeData(GlFeeData feeData) {
        requireNonNull(feeData.getFee(), "FEE", feeData);
        requireNonNull(feeData.getCreditAccount(), "CREDIT_ACCOUNT", feeData);
        requireNonNull(feeData.getDebitAccount(), "DEBIT_ACCOUNT", feeData);
        requireNonBlank(feeData.getBudgetCode(), "BUDGET_CODE", feeData);
        requireNonBlank(feeData.getTransactionCode(), "TRANSACTION_CODE", feeData);
        requireNonBlank(resolveCurrency(feeData), "CURRENCY", feeData);
        requireNonBlank(feeData.getNarrative1(), "NARRATIVE1", feeData);
        requireNonBlank(feeData.getNarrative2(), "NARRATIVE2", feeData);
        requireNonBlank(feeData.getOpu(), "OPU", feeData);
        requireNonBlank(feeData.getReportingDate(), "REPORTING_DATE", feeData);
        requireNonBlank(feeData.getValueDate(), "VALUE_DATE", feeData);
    }

    private GlBookingRequest buildRequest(GlFeeData feeData) {
        String currency = resolveCurrency(feeData);
        BigDecimal fee = feeData.getFee().setScale(2, java.math.RoundingMode.HALF_UP);

        GlBookingRequest.Item debitItem = buildItem(
                String.valueOf(feeData.getDebitAccount()),
                fee,
                currency,
                feeData,
                normalize(glFeeBookingPreparationProperties.getDebitOpu()),
                "D");

        GlBookingRequest.Item creditItem = buildItem(
                String.valueOf(feeData.getCreditAccount()),
                fee,
                currency,
                feeData,
                feeData.getOpu(),
                "C");

        GlBookingRequest.Batch batch = new GlBookingRequest.Batch();
        batch.setBatchId(feeData.getCallReplyRef());
        batch.setCurrency(currency);
        batch.setDrTotal(fee);
        batch.setCrTotal(fee);
        batch.setOriginCode(DEFAULT_ORIGIN_CODE);
        batch.setReportingDate(normalizeSoapDateTime(feeData.getReportingDate()));
        batch.setValueDate(normalizeSoapDateTime(feeData.getValueDate()));
        batch.setDebitItems(List.of(debitItem));
        batch.setCreditItems(List.of(creditItem));
        batch.setOnlyUpdate(Boolean.FALSE);
        batch.setOnlyValidation(Boolean.FALSE);

        GlBookingRequest.RequestInfo requestInfo = new GlBookingRequest.RequestInfo();
        requestInfo.setEnvironment(buildEnvironment());
        requestInfo.setUser(buildUser());
        requestInfo.setBatch(batch);
        requestInfo.setHistoryLogOn(Boolean.TRUE);

        GlBookingRequest request = new GlBookingRequest();
        request.setRequestInfo(requestInfo);
        return request;
    }

    private GlBookingRequest.Environment buildEnvironment() {
        GlBookingRequest.Environment environment = new GlBookingRequest.Environment();
        environment.setEntityCode(normalize(glFeeBookingPreparationProperties.getEntityCode()));
        environment.setRequestCode(normalize(glFeeBookingPreparationProperties.getRequestCode()));
        return environment;
    }

    private GlBookingRequest.User buildUser() {
        GlBookingRequest.User user = new GlBookingRequest.User();
        user.setNNumber(normalize(glFeeBookingPreparationProperties.getNNumber()));
        user.setUserName(normalize(glFeeBookingPreparationProperties.getUserName()));
        return user;
    }

    private void saveBookingLog(
            GlFeeData feeData,
            String referenceNumber,
            LocalDateTime requestTime,
            LocalDateTime responseTime,
            String requestXml,
            GlBookingResponse response,
            Exception exception) {
        boolean success = response != null && Boolean.TRUE.equals(response.getSuccess());
        long durationMs = requestTime != null && responseTime != null
                ? Math.max(0L, Duration.between(requestTime, responseTime).toMillis())
                : 0L;

        glFeeBookingLogRepository.save(GlFeeBookingLog.builder()
                .glFeeDataId(feeData.getId())
                .requestId(feeData.getRequestId())
                .callReplyRef(feeData.getCallReplyRef())
                .bookingStatusAtCall(feeData.getBookingStatus())
                .referenceNumber(referenceNumber)
                .requestTime(requestTime)
                .responseTime(responseTime)
                .durationMs(durationMs)
                .successFlag(success ? "Y" : "N")
                .httpStatus(response != null ? response.getHttpStatus() : null)
                .returnCode(response != null ? response.getReturnCode() : null)
                .resultCode(response != null ? response.getResultCode() : null)
                .transactionDealNumber(response != null ? response.getTransactionDealNumber() : null)
                .reversalDealNumber(response != null ? response.getReversalDealNumber() : null)
                .errorMessage(resolveErrorMessage(response, exception))
                .requestXml(requestXml)
                .responseXml(response != null ? response.getResponseXml() : null)
                .build());
    }

    private GlBookingRequest.Item buildItem(
            String account,
            BigDecimal amount,
            String currency,
            GlFeeData feeData,
            String opu,
            String drcr) {
        GlBookingRequest.Item item = new GlBookingRequest.Item();
        item.setAccount(account);
        item.setAmount(amount);
        item.setBudgetCode(feeData.getBudgetCode());
        item.setCurrency(currency);
        item.setDrcr(drcr);
        item.setNarrative1(feeData.getNarrative1());
        item.setNarrative2(feeData.getNarrative2());
        item.setOpu(opu);
        item.setReportingDate(normalizeSoapDateTime(feeData.getReportingDate()));
        item.setTransactionCode(feeData.getTransactionCode());
        item.setValueDate(normalizeSoapDateTime(feeData.getValueDate()));
        return item;
    }

    private String resolveCurrency(GlFeeData feeData) {
        String currency = normalize(feeData.getCurrency());
        return currency == null ? DEFAULT_CURRENCY : currency;
    }

    private void requireNonNull(Object value, String fieldName, GlFeeData feeData) {
        if (value == null) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Prepared GL fee data is missing " + fieldName + " for callReplyRef=" + feeData.getCallReplyRef());
        }
    }

    private void requireNonBlank(String value, String fieldName, GlFeeData feeData) {
        if (normalize(value) == null) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Prepared GL fee data is missing " + fieldName + " for callReplyRef=" + feeData.getCallReplyRef());
        }
    }

    private String resolveErrorMessage(GlBookingResponse response, Exception exception) {
        if (exception != null && exception.getMessage() != null) {
            return truncate(exception.getMessage(), MAX_ERROR_MESSAGE_LENGTH);
        }
        if (response != null && !Boolean.TRUE.equals(response.getSuccess())) {
            String message = "returnCode=" + response.getReturnCode() + ", resultCode=" + response.getResultCode();
            return truncate(message, MAX_ERROR_MESSAGE_LENGTH);
        }
        return null;
    }

    private String truncate(String value, int maxLength) {
        if (value == null || value.length() <= maxLength) {
            return value;
        }
        return value.substring(0, maxLength);
    }

    private String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private String normalizeSoapDateTime(String value) {
        String normalized = normalize(value);
        if (normalized == null) {
            return null;
        }
        if (normalized.length() == 10) {
            return normalized + "T00:00:00";
        }
        return normalized;
    }
}

