+package rs.unicredit.cbr.service;
+
+import java.time.LocalDateTime;
+import java.util.List;
+
+import lombok.RequiredArgsConstructor;
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.stereotype.Service;
+
+import rs.unicredit.cbr.model.GlFeeData;
+import rs.unicredit.cbr.repository.GlFeeDataRepository;
+
+@Service
+@RequiredArgsConstructor
+public class GlFeeEnrichingRecoveryService {
+
+    private static final Logger LOG = LoggerFactory.getLogger(GlFeeEnrichingRecoveryService.class);
+    private static final String STATUS_ENRICHING = "ENRICHING";
+    private static final String STATUS_ENRICH_ERROR = "ENRICH_ERROR";
+
+    private final GlFeeDataRepository glFeeDataRepository;
+
+    @Value("${customs.fee-booking.recover-stale-enriching.stale-minutes:10}")
+    private long staleMinutes;
+
+    public int recoverStaleEnrichingRows() {
+        LocalDateTime cutoff = LocalDateTime.now().minusMinutes(Math.max(1L, staleMinutes));
+        List<GlFeeData> staleRows = glFeeDataRepository
+                .findAllByBookingStatusAndStatusUpdatedAtBeforeOrderByIdAsc(STATUS_ENRICHING, cutoff);
+        int recoveredCount = 0;
+        for (GlFeeData staleRow : staleRows) {
+            if (staleRow == null || staleRow.getId() == null) {
+                continue;
+            }
+            int updated = glFeeDataRepository.updateBookingStatus(
+                    staleRow.getId(),
+                    STATUS_ENRICHING,
+                    STATUS_ENRICH_ERROR,
+                    LocalDateTime.now());
+            if (updated > 0) {
+                recoveredCount++;
+                LOG.warn(
+                        "Recovered stale GL fee enrichment feeDataId={} requestId={} callReplyRef={} staleSince={} nextStatus={}",
+                        staleRow.getId(),
+                        staleRow.getRequestId(),
+                        staleRow.getCallReplyRef(),
+                        staleRow.getStatusUpdatedAt(),
+                        STATUS_ENRICH_ERROR);
+            }
+        }
+        LOG.info(
+                "GL fee stale enriching recovery finished candidates={} recovered={} cutoff={}",
+                staleRows.size(),
+                recoveredCount,
+                cutoff);
+        return recoveredCount;
+    }
+}
