package rs.unicredit.cbr.service;

import java.util.concurrent.atomic.AtomicBoolean;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@ConditionalOnProperty(
        prefix = "customs.fee-booking.recover-stale-enriching",
        name = "enabled",
        havingValue = "true")
public class GlFeeEnrichingRecoveryScheduler {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeEnrichingRecoveryScheduler.class);

    private final GlFeeEnrichingRecoveryService glFeeEnrichingRecoveryService;
    private final AtomicBoolean running = new AtomicBoolean(false);

    @Scheduled(fixedDelayString = "${customs.fee-booking.recover-stale-enriching.fixed-delay-ms:300000}")
    public void recoverStaleEnrichingRows() {
        if (!running.compareAndSet(false, true)) {
            LOG.info("Skipping GL fee stale enriching recovery because previous run is still in progress.");
            return;
        }
        try {
            int recovered = glFeeEnrichingRecoveryService.recoverStaleEnrichingRows();
            LOG.info("GL fee stale enriching recovery scheduler finished recovered={}", recovered);
        } catch (Exception ex) {
            LOG.error("GL fee stale enriching recovery scheduler failed: {}", ex.getMessage(), ex);
        } finally {
            running.set(false);
        }
    }
}

