import { notification } from "antd";
import keycloak from "keycloak-js";
import { JWT_TOKEN } from "./storageKeys";
import { jwtDecode } from "jwt-decode";

const keycloakInstance = new keycloak(process.env.ENV_KEYCLOAK_URL);

keycloakInstance.onTokenExpired = () => updateToken();

const loginUser = (onLoggedInCallback) => {
  keycloakInstance
    .init({ onLoad: 'login-required' })
    .then((authenticated) => {
      if (authenticated) {
        onLoggedInCallback();
      } else
        notification['error']({
          message: 'You are not allowed to access',
        });
    })
    .catch((e) => {
      console.log(`keycloak exception: ${e}`);
    });
};

const logoutUser = () => {
  keycloakInstance.logout();
};

const getUsername = () => getParsedToken()?.username;

const getName = () => getParsedToken()?.given_name;

const getSurname = () => getParsedToken()?.family_name;

const getEmail = () => getParsedToken()?.email;

const getUserRoles = () =>
  getParsedToken()?.realm_access === undefined
    ? []
    : getParsedToken()?.realm_access?.roles;

const isAuthorized = (requiredRoles) => {
  const roles = [...requiredRoles];
  const userRoles = getUserRoles();
  return roles.length === 0 || roles.some((role) => userRoles.includes(role));
};

const isLoggedIn = () => !!keycloakInstance.token;

const normalizeToken = (token) => {
  if (!token) return null;
  return token.startsWith("Bearer ") ? token.slice("Bearer ".length) : token;
};

const getToken = () => {
  if (process.env.ENV_START_TYPE === 'isolation') return keycloakInstance.token;
  return normalizeToken(localStorage.getItem(JWT_TOKEN));
};

const getParsedToken = () => {
  if (process.env.ENV_START_TYPE === 'isolation')
    return keycloakInstance.tokenParsed;
  const token = normalizeToken(localStorage.getItem(JWT_TOKEN));
  if (!token) return null;
  return jwtDecode(token);
};

const doLogin = keycloakInstance.login;

const updateToken = () => keycloakInstance.updateToken(5).then().catch(doLogin);

export const isKeycloakInUsage = () => {
  return (
    process.env.ENV_START_TYPE === "isolation" &&
    process.env.ENV_AUTH_TYPE !== "local"
  );
};

export const isInContainer = () => {
  process.env.ENV_START_TYPE !== "isolation" &&
    process.env.ENV_AUTH_TYPE !== "local";
};

const KeyCloakService = {
  loginUser,
  getUsername,
  getName,
  getSurname,
  getEmail,
  getUserRoles,
  logoutUser,
  isLoggedIn,
  getToken,
  updateToken,
  isAuthorized,
};

export default KeyCloakService;

